import{_ as e,o as t,c as o,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"Ceph RGW Bucket Snapshots- Beyond Versioning - Yehuda Sadeh Weinraub, Ubiquiti","description":"","frontmatter":{"title":"Ceph RGW Bucket Snapshots- Beyond Versioning - Yehuda Sadeh Weinraub, Ubiquiti","date":"2025-11-19T00:00:00.000Z","updated":"2025-11-20T00:00:00.000Z","tags":["Ceph","RGW","Bucket Snapshots","Object Storage","Data Backup"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Ceph_RGW_Bucket_Snapshots_-_Beyond_Versioning_-_Yehuda_Sadeh_Weinraub_Ubiquiti.md","filePath":"posts/2025/Ceph_RGW_Bucket_Snapshots_-_Beyond_Versioning_-_Yehuda_Sadeh_Weinraub_Ubiquiti.md","lastUpdated":1780459816000}'),n={name:"posts/2025/Ceph_RGW_Bucket_Snapshots_-_Beyond_Versioning_-_Yehuda_Sadeh_Weinraub_Ubiquiti.md"};function s(r,a,l,h,u,d){return t(),o("div",null,[...a[0]||(a[0]=[i('<h3 id="ceph-rgw-bucket-snapshots-会议纪要" tabindex="-1">Ceph RGW Bucket Snapshots 会议纪要 <a class="header-anchor" href="#ceph-rgw-bucket-snapshots-会议纪要" aria-label="Permalink to &quot;Ceph RGW Bucket Snapshots 会议纪要&quot;">​</a></h3><h4 id="会议主题" tabindex="-1">会议主题 <a class="header-anchor" href="#会议主题" aria-label="Permalink to &quot;会议主题&quot;">​</a></h4><p>本次会议主要讨论了 Ceph RGW（RADOS Gateway）Bucket Snapshots 功能的开发进展、设计原理、实现细节及未来规划。主讲人 Yehuda Sadeh（前 IBM 员工，现 Ubiquiti 成员）介绍了该功能的背景、技术挑战及当前实现状态，并由 Shilpa（RGW 团队）接手后续开发。</p><h4 id="关键讨论内容" tabindex="-1">关键讨论内容 <a class="header-anchor" href="#关键讨论内容" aria-label="Permalink to &quot;关键讨论内容&quot;">​</a></h4><h5 id="背景与动机" tabindex="-1">背景与动机 <a class="header-anchor" href="#背景与动机" aria-label="Permalink to &quot;背景与动机&quot;">​</a></h5><ul><li><strong>现有备份方案的局限性</strong>：当前 RGW 备份主要依赖 Activity Logs，但存在同步生成、数据一致性差等问题。</li><li><strong>S3 Object Versioning 的局限性</strong>：支持归档，但无法保证跨对象的一致性，且可能导致数据膨胀。</li></ul><h5 id="bucket-snapshots-功能设计" tabindex="-1">Bucket Snapshots 功能设计 <a class="header-anchor" href="#bucket-snapshots-功能设计" aria-label="Permalink to &quot;Bucket Snapshots 功能设计&quot;">​</a></h5><ul><li><strong>核心能力</strong>：用户可对 Bucket 启用快照功能，支持创建、删除、列出快照（非管理员操作），并访问历史快照中的对象数据。</li><li><strong>实现原理</strong>：扩展 Object Versioning，引入 snapID 作为新维度，通过 OH（Object Logical Head）跟踪对象在不同快照中的最新实例。</li></ul><h5 id="技术挑战与解决方案" tabindex="-1">技术挑战与解决方案 <a class="header-anchor" href="#技术挑战与解决方案" aria-label="Permalink to &quot;技术挑战与解决方案&quot;">​</a></h5><ul><li><strong>对象覆盖处理</strong>：通过 snapID 区分不同版本的对象。</li><li><strong>快照删除与清理</strong>：删除快照时触发 Lifecycle 进程，检查对象是否被其他快照引用，仅清理无引用的对象。</li><li><strong>多站点限制</strong>：当前为 Zone-local 功能，快照不会跨 Zone 同步。</li><li><strong>性能与扩展性</strong>：限制单 Bucket 的快照数量，避免 OMAP 数据膨胀和 Bucket Index 过载。</li></ul><h5 id="演示与-api-扩展" tabindex="-1">演示与 API 扩展 <a class="header-anchor" href="#演示与-api-扩展" aria-label="Permalink to &quot;演示与 API 扩展&quot;">​</a></h5><ul><li><strong>Demo 关键操作</strong>：创建 Bucket → 启用快照 → 生成快照 → 覆盖对象 → 生成新快照。</li><li><strong>新增 S3 API 参数</strong>：<code>snap_id</code>（指定快照版本），<code>snap_range</code>（查询快照范围变更）。</li></ul><h5 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h5><ol><li><strong>功能完善</strong>：增强多站点支持，优化快照一致性。</li><li><strong>测试与验证</strong>：扩大测试覆盖。</li><li><strong>性能调优</strong>：监控 Bucket Index 负载，评估 Shard 数量计算公式。</li></ol><h4 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h4><p>RGW Bucket Snapshots 为 Ceph 提供了更灵活的备份和版本管理能力，目前功能已接近完成，后续将聚焦于多站点集成和性能优化。社区可通过测试和反馈推动其成熟。</p><h4 id="q-a-重点摘要" tabindex="-1">Q&amp;A 重点摘要 <a class="header-anchor" href="#q-a-重点摘要" aria-label="Permalink to &quot;Q&amp;A 重点摘要&quot;">​</a></h4><ul><li><strong>快照创建是否加锁</strong>？目前无锁，应用需自行暂停写入以确保一致性。</li><li><strong>Shard 数量如何规划</strong>？需综合考虑对象数量、快照数量及写入频率。</li><li><strong>元数据操作是否加剧 PG 压力</strong>？通过限制快照数量缓解，但需长期监控。</li></ul>',18)])])}const p=e(n,[["render",s]]);export{_ as __pageData,p as default};
